'use client';

import { IconPlaceholder } from '@/components/icon-placeholder';
import {
  BaseBlockquotePlugin,
  BaseCodeBlockPlugin,
  BaseHeadingPlugin,
  BaseHorizontalRulePlugin,
  BaseListPlugin,
  BaseParagraphPlugin,
  PLUGINS,
} from 'platejs';
import { BaseDatePlugin } from 'platejs/date';
import { BaseDetailsPlugin } from 'platejs/details';
import { BaseExcalidrawPlugin } from 'platejs/excalidraw';
import { BaseFootnotePlugin } from 'platejs/footnote';
import { BaseColumnGroupPlugin } from 'platejs/layout';
import { BaseEquationPlugin, BaseInlineEquationPlugin } from 'platejs/math';
import { BaseImagePlugin, BaseMediaEmbedPlugin } from 'platejs/media';
import { type Editor, useEditor, useEditorReadOnly } from 'platejs/react';
import { BaseTablePlugin } from 'platejs/table';
import { BaseTocPlugin } from 'platejs/toc';
import * as React from 'react';

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/registry/components/editor/dropdown-menu';
import {
  ToolbarButton,
  ToolbarMenuGroup,
} from '@/registry/components/editor/toolbar';

import { linkPlugin } from './link';

type Item = {
  icon: React.ReactNode;
  onSelect: () => void;
  value: string;
  focusEditor?: boolean;
  label?: string;
};

type Group = {
  group: string;
  items: Item[];
};

const canRestoreFocus = (
  editor: Editor,
  ownerDocument: Document | undefined,
  activeElement: Element | null | undefined
) => {
  const editable = editor.api.dom.editable();
  const currentActiveElement = ownerDocument?.activeElement;

  return (
    editable?.isConnected === true &&
    !editor.read.view.isReadOnly() &&
    (!currentActiveElement ||
      currentActiveElement === ownerDocument?.body ||
      currentActiveElement === activeElement)
  );
};

function getGroups(editor: Editor): Group[] {
  const groups: Group[] = [];
  const basicBlocks: Item[] = [];
  const lists: Item[] = [];
  const media: Item[] = [];
  const advancedBlocks: Item[] = [];
  const inline: Item[] = [];
  const paragraph = editor.plugin(BaseParagraphPlugin);
  const heading = editor.plugin(BaseHeadingPlugin);
  const list = editor.plugin(BaseListPlugin);
  const table = editor.plugin(BaseTablePlugin);
  const codeBlock = editor.plugin(BaseCodeBlockPlugin);
  const blockquote = editor.plugin(BaseBlockquotePlugin);
  const horizontalRule = editor.plugin(BaseHorizontalRulePlugin);
  const details = editor.plugin(BaseDetailsPlugin);
  const image = editor.plugin(BaseImagePlugin);
  const mediaEmbed = editor.plugin(BaseMediaEmbedPlugin);
  const toc = editor.plugin(BaseTocPlugin);
  const column = editor.plugin(BaseColumnGroupPlugin);
  const equation = editor.plugin(BaseEquationPlugin);
  const excalidraw = editor.plugin(BaseExcalidrawPlugin);
  const link = editor.plugin(linkPlugin);
  const date = editor.plugin(BaseDatePlugin);
  const footnote = editor.plugin(BaseFootnotePlugin);
  const inlineEquation = editor.plugin(BaseInlineEquationPlugin);

  if (paragraph.installed) {
    basicBlocks.push({
      icon: <IconPlaceholder lucide="PilcrowIcon" tabler="IconPilcrow" hugeicons="ParagraphIcon" phosphor="ParagraphIcon" remixicon="RiParagraph" />,
      label: 'Paragraph',
      value: PLUGINS.paragraph,
      onSelect: () => {
        const current = editor.plugin(BaseParagraphPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseParagraphPlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (heading.installed) {
    (
      [
        ['heading-1', 'Heading 1', <IconPlaceholder lucide="Heading1Icon" tabler="IconH1" hugeicons="Heading01Icon" phosphor="TextHOneIcon" remixicon="RiH1" key="heading-1" />, 1],
        ['heading-2', 'Heading 2', <IconPlaceholder lucide="Heading2Icon" tabler="IconH2" hugeicons="Heading02Icon" phosphor="TextHTwoIcon" remixicon="RiH2" key="heading-2" />, 2],
        ['heading-3', 'Heading 3', <IconPlaceholder lucide="Heading3Icon" tabler="IconH3" hugeicons="Heading03Icon" phosphor="TextHThreeIcon" remixicon="RiH3" key="heading-3" />, 3],
      ] as const
    ).forEach(([value, label, icon, level]) => {
      basicBlocks.push({
        icon,
        label,
        value,
        onSelect: () => {
          const current = editor.plugin(BaseHeadingPlugin);

          if (!current.installed || editor.read.view.isReadOnly()) return;

          editor.update((tx) => {
            tx.plugin(BaseHeadingPlugin).insert({ level }, { select: true });
          });
        },
      });
    });
  }

  if (table.installed) {
    basicBlocks.push({
      icon: <IconPlaceholder lucide="TableIcon" tabler="IconTable" hugeicons="TableIcon" phosphor="TableIcon" remixicon="RiTableLine" />,
      label: 'Table',
      value: PLUGINS.table,
      onSelect: () => {
        const current = editor.plugin(BaseTablePlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseTablePlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (codeBlock.installed) {
    basicBlocks.push({
      icon: <IconPlaceholder lucide="FileCodeIcon" tabler="IconFileCode" hugeicons="File01Icon" phosphor="FileCodeIcon" remixicon="RiFileCodeLine" />,
      label: 'Code',
      value: PLUGINS.codeBlock,
      onSelect: () => {
        const current = editor.plugin(BaseCodeBlockPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseCodeBlockPlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (blockquote.installed) {
    basicBlocks.push({
      icon: <IconPlaceholder lucide="QuoteIcon" tabler="IconQuote" hugeicons="QuoteDownIcon" phosphor="QuotesIcon" remixicon="RiDoubleQuotesL" />,
      label: 'Quote',
      value: PLUGINS.blockquote,
      onSelect: () => {
        const current = editor.plugin(BaseBlockquotePlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseBlockquotePlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (horizontalRule.installed) {
    basicBlocks.push({
      icon: <IconPlaceholder lucide="MinusIcon" tabler="IconMinus" hugeicons="MinusSignIcon" phosphor="MinusIcon" remixicon="RiSubtractLine" />,
      label: 'Divider',
      value: PLUGINS.horizontalRule,
      onSelect: () => {
        const current = editor.plugin(BaseHorizontalRulePlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseHorizontalRulePlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (list.installed) {
    (
      [
        [
          'disc',
          'Bulleted list',
          <IconPlaceholder lucide="ListIcon" tabler="IconListDetails" hugeicons="Menu01Icon" phosphor="ListIcon" remixicon="RiListUnordered" key="disc" className="[&:dir(rtl)]:-scale-x-100" />,
          'bulleted',
        ],
        [
          'decimal',
          'Numbered list',
          <IconPlaceholder lucide="ListOrderedIcon" tabler="IconListNumbers" hugeicons="LeftToRightListNumberIcon" phosphor="ListNumbersIcon" remixicon="RiListOrdered" key="decimal" />,
          'numbered',
        ],
        ['todo', 'To-do list', <IconPlaceholder lucide="SquareIcon" tabler="IconPlayerStop" hugeicons="StopCircleIcon" phosphor="StopCircleIcon" remixicon="RiStopCircleLine" key="todo" />, 'task'],
      ] as const
    ).forEach(([value, label, icon, type]) => {
      lists.push({
        icon,
        label,
        value,
        onSelect: () => {
          if (
            !editor.plugin(BaseListPlugin).installed ||
            editor.read.view.isReadOnly()
          ) {
            return;
          }

          editor.update((tx) => {
            tx.plugin(BaseListPlugin).insert({ type }, { select: true });
          });
        },
      });
    });
  }

  if (details.installed) {
    lists.push({
      icon: <IconPlaceholder lucide="ChevronRightIcon" tabler="IconChevronRight" hugeicons="ArrowRight01Icon" phosphor="CaretRightIcon" remixicon="RiArrowRightSLine" className="[&:dir(rtl)]:rotate-180" />,
      label: 'Details',
      value: PLUGINS.details,
      onSelect: () => {
        const current = editor.plugin(BaseDetailsPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseDetailsPlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (image.installed) {
    media.push({
      focusEditor: false,
      icon: <IconPlaceholder lucide="ImageIcon" tabler="IconPhoto" hugeicons="Image01Icon" phosphor="ImageIcon" remixicon="RiImageLine" />,
      label: 'Image',
      value: PLUGINS.image,
      onSelect: () => {
        const current = editor.plugin(BaseImagePlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        const editable = editor.api.dom.editable();
        const ownerDocument = editable?.ownerDocument;
        const activeElement = ownerDocument?.activeElement;

        void current.api
          .insertUrl(
            // oxlint-disable-next-line no-alert -- This copied menu owns its URL input policy.
            () => window.prompt('Enter the URL of the image'),
            { select: true }
          )
          .then((inserted) => {
            if (
              inserted &&
              canRestoreFocus(editor, ownerDocument, activeElement)
            ) {
              editor.api.dom.focus();
            }
          })
          .catch((error: unknown) => {
            console.error('Could not insert the image URL.', error);
          });
      },
    });
  }

  if (mediaEmbed.installed) {
    media.push({
      focusEditor: false,
      icon: <IconPlaceholder lucide="FilmIcon" tabler="IconMovie" hugeicons="Film01Icon" phosphor="FilmStripIcon" remixicon="RiFilmLine" />,
      label: 'Embed',
      value: PLUGINS.mediaEmbed,
      onSelect: () => {
        const current = editor.plugin(BaseMediaEmbedPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        const editable = editor.api.dom.editable();
        const ownerDocument = editable?.ownerDocument;
        const activeElement = ownerDocument?.activeElement;

        void current.api
          .insertUrl(
            // oxlint-disable-next-line no-alert -- This copied menu owns its URL input policy.
            () => window.prompt('Enter the URL of the embed'),
            { select: true }
          )
          .then((inserted) => {
            if (
              inserted &&
              canRestoreFocus(editor, ownerDocument, activeElement)
            ) {
              editor.api.dom.focus();
            }
          })
          .catch((error: unknown) => {
            console.error('Could not insert the embed URL.', error);
          });
      },
    });
  }

  if (toc.installed) {
    advancedBlocks.push({
      icon: <IconPlaceholder lucide="TableOfContentsIcon" tabler="IconListDetails" hugeicons="LeftToRightListBulletIcon" phosphor="ListBulletsIcon" remixicon="RiListIndefinite" />,
      label: 'Table of contents',
      value: PLUGINS.toc,
      onSelect: () => {
        const current = editor.plugin(BaseTocPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseTocPlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (column.installed) {
    advancedBlocks.push({
      icon: <IconPlaceholder lucide="Columns3Icon" tabler="IconLayoutColumns" hugeicons="LeftToRightListBulletIcon" phosphor="ColumnsIcon" remixicon="RiLayoutColumnLine" />,
      label: '3 columns',
      value: 'action_three_columns',
      onSelect: () => {
        const current = editor.plugin(BaseColumnGroupPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseColumnGroupPlugin).insert(
            { columns: 3 },
            { select: true }
          );
        });
      },
    });
  }

  if (equation.installed) {
    advancedBlocks.push({
      focusEditor: false,
      icon: <IconPlaceholder lucide="RadicalIcon" tabler="IconSquareRoot" hugeicons="SquareRootSquareIcon" phosphor="RadicalIcon" remixicon="RiSquareRoot" />,
      label: 'Equation',
      value: PLUGINS.equation,
      onSelect: () => {
        const current = editor.plugin(BaseEquationPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseEquationPlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (excalidraw.installed) {
    advancedBlocks.push({
      icon: <IconPlaceholder lucide="PenToolIcon" tabler="IconVectorBezier" hugeicons="PenTool03Icon" phosphor="PenNibIcon" remixicon="RiPenNibLine" />,
      label: 'Excalidraw',
      value: PLUGINS.excalidraw,
      onSelect: () => {
        const current = editor.plugin(BaseExcalidrawPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        editor.update((tx) => {
          tx.plugin(BaseExcalidrawPlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (link.installed) {
    inline.push({
      focusEditor: false,
      icon: <IconPlaceholder lucide="Link2Icon" tabler="IconLink" hugeicons="Link05Icon" phosphor="LinkSimpleHorizontalIcon" remixicon="RiLinkM" />,
      label: 'Link',
      value: PLUGINS.link,
      onSelect: () => {
        const current = editor.plugin(linkPlugin);

        if (!current.installed || editor.read.view.isReadOnly()) return;

        current.store.set({ text: editor.read.text.string() });
        current.api.show('insert', editor.id);
      },
    });
  }

  if (date.installed) {
    inline.push({
      icon: <IconPlaceholder lucide="CalendarIcon" tabler="IconCalendar" hugeicons="Calendar03Icon" phosphor="CalendarIcon" remixicon="RiCalendarLine" />,
      label: 'Date',
      value: PLUGINS.date,
      onSelect: () => {
        if (
          !editor.plugin(BaseDatePlugin).installed ||
          editor.read.view.isReadOnly()
        ) {
          return;
        }

        editor.update((tx) => {
          tx.plugin(BaseDatePlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (footnote.installed) {
    inline.push({
      icon: <IconPlaceholder lucide="SuperscriptIcon" tabler="IconSuperscript" hugeicons="TextSuperscriptIcon" phosphor="TextSuperscriptIcon" remixicon="RiSuperscript" />,
      label: 'Footnote',
      value: 'action_footnote',
      onSelect: () => {
        if (
          !editor.plugin(BaseFootnotePlugin).installed ||
          editor.read.view.isReadOnly()
        ) {
          return;
        }

        editor.update((tx) => {
          tx.plugin(BaseFootnotePlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (inlineEquation.installed) {
    inline.push({
      focusEditor: false,
      icon: <IconPlaceholder lucide="RadicalIcon" tabler="IconSquareRoot" hugeicons="SquareRootSquareIcon" phosphor="RadicalIcon" remixicon="RiSquareRoot" />,
      label: 'Inline Equation',
      value: PLUGINS.inlineEquation,
      onSelect: () => {
        if (
          !editor.plugin(BaseInlineEquationPlugin).installed ||
          editor.read.view.isReadOnly()
        ) {
          return;
        }

        editor.update((tx) => {
          tx.plugin(BaseInlineEquationPlugin).insert({}, { select: true });
        });
      },
    });
  }

  if (basicBlocks.length > 0) {
    groups.push({ group: 'Basic blocks', items: basicBlocks });
  }
  if (lists.length > 0) groups.push({ group: 'Lists', items: lists });
  if (media.length > 0) groups.push({ group: 'Media', items: media });
  if (advancedBlocks.length > 0) {
    groups.push({ group: 'Advanced blocks', items: advancedBlocks });
  }
  if (inline.length > 0) groups.push({ group: 'Inline', items: inline });

  return groups;
}

export function InsertToolbarButton() {
  const editor = useEditor();
  const readOnly = useEditorReadOnly();
  const [open, setOpen] = React.useState(false);
  const groups = getGroups(editor);

  return (
    <DropdownMenu open={open} onOpenChange={setOpen} modal={false}>
      <DropdownMenuTrigger>
        <ToolbarButton
          disabled={readOnly || groups.length === 0}
          pressed={open}
          tooltip="Insert"
          isDropdown
        >
          <IconPlaceholder lucide="PlusIcon" tabler="IconPlus" hugeicons="Add01Icon" phosphor="PlusIcon" remixicon="RiAddLine" />
        </ToolbarButton>
      </DropdownMenuTrigger>

      <DropdownMenuContent
        className="flex max-h-[500px] min-w-0 flex-col overflow-y-auto"
        align="start"
      >
        {groups.map(({ group, items }) => (
          <ToolbarMenuGroup key={group} label={group}>
            {items.map(
              ({ focusEditor = true, icon, label, value, onSelect }) => (
                <DropdownMenuItem
                  key={value}
                  className="min-w-[180px]"
                  finalFocus={
                    focusEditor
                      ? () => {
                          if (!editor.read.view.isReadOnly()) {
                            editor.api.dom.focus();
                          }
                        }
                      : false
                  }
                  onSelect={onSelect}
                >
                  {icon}
                  {label}
                </DropdownMenuItem>
              )
            )}
          </ToolbarMenuGroup>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
